#pragma once

#include <functional>
#include <vector>

// Event: the C++ stand in for a C# event. Do not edit this file.
//
// It keeps a list of handlers. Every handler takes (sender, e), the same
// two parameters a C# handler takes.
//
//     int ticket = bar.OrderReady.subscribe(handler);     subscribe
//     bar.OrderReady.unsubscribe(ticket);                 unsubscribe
//     OrderReady.invoke(this, OrderEventArgs(order));     raise it
//
// C++ has no event keyword, so nothing stops another class from calling
// invoke. By convention, only the class that owns the event raises it.
//
// C++ cannot compare two std::function objects, so it cannot find a
// handler by looking at it. Instead, subscribe hands back a ticket number,
// and unsubscribe takes that ticket. A class that needs to stop listening
// keeps its ticket in a field.

// EmptyArgs: the details for an event that has no details to send, like
// AllCaughtUp. It is the C++ stand in for C#'s EventArgs.Empty.
struct EmptyArgs
{
};

template <typename Args>
class Event
{
public:
    // The shape every handler must have.
    using Handler = std::function<void(const void* sender, const Args& e)>;

    // Adds a handler to the end of the list and returns its ticket.
    int subscribe(Handler handler)
    {
        nextTicket++;
        subscriptions.push_back(Subscription{nextTicket, handler});
        return nextTicket;
    }

    // Removes the handler that holds this ticket. Any other ticket changes nothing.
    void unsubscribe(int ticket)
    {
        std::vector<Subscription> kept;
        for (const Subscription& subscription : subscriptions)
        {
            if (subscription.ticket != ticket)
            {
                kept.push_back(subscription);
            }
        }
        subscriptions = kept;
    }

    // Raises the event: runs every handler in the order they subscribed.
    // It loops over a copy, so a handler that unsubscribes cannot upset the loop.
    void invoke(const void* sender, const Args& e) const
    {
        std::vector<Subscription> copy = subscriptions;
        for (const Subscription& subscription : copy)
        {
            subscription.handler(sender, e);
        }
    }

private:
    // One handler and the ticket that names it.
    struct Subscription
    {
        int ticket;
        Handler handler;
    };

    std::vector<Subscription> subscriptions;
    int nextTicket = 0;
};
